window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fdae0f71934f9b8a"]={"versions": [{"id": "FIG-fdae0f71934f9b8a", "releases": ["R21-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Zustandsdiagramm (State Machine Diagram) zur Definition des formalen Laufzeitmodells.\n</li><li><strong>Architektur-Kontext:</strong>\n<ul class=\"fig-list\"><li><strong>Modul:</strong> ARTI (<em>AUTOSAR Run-Time Interface</em>, Classic Platform R21-11 / R24-11).\n</li><li><strong>Zweck:</strong> Standardisierung des formalen Zustandsmodells für Kategorie-1-Interrupt-Service-Routinen (<code>CAT1 ISR</code>) zur Erfassung durch externe Timing-, Trace- und Debug-Werkzeuge (z. B. Profiling, Laufzeit- und Latenzanalysen).\n</li><li><strong>Einordnung:</strong> CAT1-ISRs umgehen den AUTOSAR-OS-Kontext und werden direkt über den Hardware-Interrupt-Vektor bedient (ohne OS-Scheduling-Overhead). Das Zustandsmodell abstrahiert daher alle OS-verwalteten Zwischenzustände (wie <code>Ready</code>, <code>Waiting</code> oder <code>Suspended</code>) auf eine rein binäre Ausführungslogik.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände (States):</strong>\n<ul class=\"fig-list\"><li><strong><code>Inactive</code>:</strong> Die Interrupt-Service-Routine ist passiv, d. h. es findet keine Befehlsausführung dieser ISR auf dem Core statt.\n</li><li><strong><code>Running</code>:</strong> Die CAT1-ISR befindet sich in aktiver Ausführung auf der zugewiesenen CPU/Core.\n</li></ul>\n</li><li><strong>Transitionen &amp; Events:</strong>\n<ul class=\"fig-list\"><li><strong><code>Start</code>:</strong> Zustandswechsel von <code>Inactive</code> nach <code>Running</code>. Korrespondiert semantisch mit dem Eintrittszeitpunkt in die ISR-Routine (Hook/Trace-Point).\n</li><li><strong><code>Stop</code>:</strong> Zustandswechsel von <code>Running</code> nach <code>Inactive</code>. Korrespondiert mit dem Austrittszeitpunkt unmittelbar vor Rücksprung aus dem Interrupt-Kontext (<code>RETI</code>/<code>ERET</code>).\n</li></ul>\n</li><li><strong>Metamodell-Bezug:</strong>\n<ul class=\"fig-list\"><li>Bindung an das ARTI-Metamodell-Element <code>ArtiCat1Isr</code>.\n</li><li>Da CAT1-ISRs nicht über OS-Task-/Resource-Deskriptoren verwaltet werden, existieren keine OS-Synchronisations- oder Sperrmechanismen (keine OS-Spinlocks, Events oder Ressourcen-Bindungen im Modell).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Ruhezustand:</strong> Die ISR verweilt im Zustand <code>Inactive</code>.\n</li><li><strong>Interrupt-Eintritt (<code>Start</code>):</strong>\n<ul class=\"fig-list\"><li>Hardware-Interrupt triggert den Vektorsprung.\n</li><li>Im Prolog der CAT1-ISR feuert der ARTI-Trace-Hook (z. B. Write auf Instrumentierungsadresse oder Software-Breakpoint/Trace-Marker).\n</li><li>Die Transition nach <code>Running</code> wird signalisiert.\n</li></ul>\n</li><li><strong>Ausführungsphase (<code>Running</code>):</strong>\n<ul class=\"fig-list\"><li>Abarbeitung des applikativen bzw. treiberspezifischen ISR-Payloads im Interrupt-Kontext.\n</li><li>Präemption durch höher priorisierte Interrupts (Nested ISRs) unterbricht die physische Ausführung, verändert im ARTI-Zustandsmodell der unterbrochenen ISR jedoch nicht zwingend deren Status <code>Running</code> (die Rekonstruktion der aktiven Core-Belegung obliegt dem Trace-Tool über den Core-Kontext).\n</li></ul>\n</li><li><strong>Interrupt-Austritt (<code>Stop</code>):</strong>\n<ul class=\"fig-list\"><li>Unmittelbar vor Abschluss des ISR-Epilogs feuert der korrespondierende ARTI-Exit-Hook.\n</li><li>Transition zurück in den Zustand <code>Inactive</code>.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Instrumentierung &amp; Overhead (Treiber/MCAL/BSW):</strong>\n<ul class=\"fig-list\"><li>Da CAT1-ISRs für extrem latenzkritische Pfade gewählt werden, müssen die ARTI-Trace-Punkte (<code>Start</code>, <code>Stop</code>) manuell oder via Codegenerator minimal-invasiv implementiert werden (bevorzugt Single-Cycle Memory/DWT-Writes statt funktionaler Callbacks).\n</li></ul>\n</li><li><strong>API-Einschränkungen:</strong>\n<ul class=\"fig-list\"><li>Im Zustand <code>Running</code> dürfen keinerlei AUTOSAR-OS-APIs aufgerufen werden, die eine Kontextumschaltung oder OS-Fehlerbehandlung erfordern (striktes CAT1-Paradigma).\n</li></ul>\n</li><li><strong>Trace- &amp; Tool-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>ARTI-Generatoren exportieren die Hooks in die ARTI-Beschreibungsdatei (<code>.arxml</code>), um Rekonstruktions-Tools mit den physikalischen Adressen/IDs der <code>Start</code>- und <code>Stop</code>-Events zu synchronisieren.\n</li><li>Fehlt die Instrumentierung an einem der beiden Übergänge, resultiert dies in inkonsistenten Tool-Metriken (Dauerlauf-Fehldetektion oder fehlende Aktivierungszählung).\n</li></ul>\n</li></ul>"}, {"id": "FIG-79db1f2e03f8ee0e", "releases": ["R22-11", "R23-11", "R25-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Zustandsdiagramm (State Machine Diagram) zur Definition des formalen Laufzeitmodells.\n</li><li><strong>Architektur-Kontext:</strong>\n<ul class=\"fig-list\"><li><strong>Modul:</strong> ARTI (<em>AUTOSAR Run-Time Interface</em>, Classic Platform R21-11 / R24-11).\n</li><li><strong>Zweck:</strong> Standardisierung des formalen Zustandsmodells für Kategorie-1-Interrupt-Service-Routinen (<code>CAT1 ISR</code>) zur Erfassung durch externe Timing-, Trace- und Debug-Werkzeuge (z. B. Profiling, Laufzeit- und Latenzanalysen).\n</li><li><strong>Einordnung:</strong> CAT1-ISRs umgehen den AUTOSAR-OS-Kontext und werden direkt über den Hardware-Interrupt-Vektor bedient (ohne OS-Scheduling-Overhead). Das Zustandsmodell abstrahiert daher alle OS-verwalteten Zwischenzustände (wie <code>Ready</code>, <code>Waiting</code> oder <code>Suspended</code>) auf eine rein binäre Ausführungslogik.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Zustände (States):</strong>\n<ul class=\"fig-list\"><li><strong><code>Inactive</code>:</strong> Die Interrupt-Service-Routine ist passiv, d. h. es findet keine Befehlsausführung dieser ISR auf dem Core statt.\n</li><li><strong><code>Running</code>:</strong> Die CAT1-ISR befindet sich in aktiver Ausführung auf der zugewiesenen CPU/Core.\n</li></ul>\n</li><li><strong>Transitionen &amp; Events:</strong>\n<ul class=\"fig-list\"><li><strong><code>Start</code>:</strong> Zustandswechsel von <code>Inactive</code> nach <code>Running</code>. Korrespondiert semantisch mit dem Eintrittszeitpunkt in die ISR-Routine (Hook/Trace-Point).\n</li><li><strong><code>Stop</code>:</strong> Zustandswechsel von <code>Running</code> nach <code>Inactive</code>. Korrespondiert mit dem Austrittszeitpunkt unmittelbar vor Rücksprung aus dem Interrupt-Kontext (<code>RETI</code>/<code>ERET</code>).\n</li></ul>\n</li><li><strong>Metamodell-Bezug:</strong>\n<ul class=\"fig-list\"><li>Bindung an das ARTI-Metamodell-Element <code>ArtiCat1Isr</code>.\n</li><li>Da CAT1-ISRs nicht über OS-Task-/Resource-Deskriptoren verwaltet werden, existieren keine OS-Synchronisations- oder Sperrmechanismen (keine OS-Spinlocks, Events oder Ressourcen-Bindungen im Modell).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Ruhezustand:</strong> Die ISR verweilt im Zustand <code>Inactive</code>.\n</li><li><strong>Interrupt-Eintritt (<code>Start</code>):</strong>\n<ul class=\"fig-list\"><li>Hardware-Interrupt triggert den Vektorsprung.\n</li><li>Im Prolog der CAT1-ISR feuert der ARTI-Trace-Hook (z. B. Write auf Instrumentierungsadresse oder Software-Breakpoint/Trace-Marker).\n</li><li>Die Transition nach <code>Running</code> wird signalisiert.\n</li></ul>\n</li><li><strong>Ausführungsphase (<code>Running</code>):</strong>\n<ul class=\"fig-list\"><li>Abarbeitung des applikativen bzw. treiberspezifischen ISR-Payloads im Interrupt-Kontext.\n</li><li>Präemption durch höher priorisierte Interrupts (Nested ISRs) unterbricht die physische Ausführung, verändert im ARTI-Zustandsmodell der unterbrochenen ISR jedoch nicht zwingend deren Status <code>Running</code> (die Rekonstruktion der aktiven Core-Belegung obliegt dem Trace-Tool über den Core-Kontext).\n</li></ul>\n</li><li><strong>Interrupt-Austritt (<code>Stop</code>):</strong>\n<ul class=\"fig-list\"><li>Unmittelbar vor Abschluss des ISR-Epilogs feuert der korrespondierende ARTI-Exit-Hook.\n</li><li>Transition zurück in den Zustand <code>Inactive</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Instrumentierung &amp; Overhead (Treiber/MCAL/BSW):</strong>\n<ul class=\"fig-list\"><li>Da CAT1-ISRs für extrem latenzkritische Pfade gewählt werden, müssen die ARTI-Trace-Punkte (<code>Start</code>, <code>Stop</code>) manuell oder via Codegenerator minimal-invasiv implementiert werden (bevorzugt Single-Cycle Memory/DWT-Writes statt funktionaler Callbacks).\n</li></ul>\n</li><li><strong>API-Einschränkungen:</strong>\n<ul class=\"fig-list\"><li>Im Zustand <code>Running</code> dürfen keinerlei AUTOSAR-OS-APIs aufgerufen werden, die eine Kontextumschaltung oder OS-Fehlerbehandlung erfordern (striktes CAT1-Paradigma).\n</li></ul>\n</li><li><strong>Trace- &amp; Tool-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>ARTI-Generatoren exportieren die Hooks in die ARTI-Beschreibungsdatei (<code>.arxml</code>), um Rekonstruktions-Tools mit den physikalischen Adressen/IDs der <code>Start</code>- und <code>Stop</code>-Events zu synchronisieren.\n</li><li>Fehlt die Instrumentierung an einem der beiden Übergänge, resultiert dies in inkonsistenten Tool-Metriken (Dauerlauf-Fehldetektion oder fehlende Aktivierungszählung).\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-fdae0f71934f9b8a", "to": "FIG-79db1f2e03f8ee0e", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-79db1f2e03f8ee0e", "to": "FIG-fdae0f71934f9b8a", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
